import{B as e,F as t,I as n,L as r,M as i,R as a,Z as o,wt as s}from"./chunks/framework.BLmRAsdY.js";import{n as c,t as l}from"./chunks/Canvas.C_CUnsxH.js";var u=JSON.parse(`{"title":"客户端加密 v2.1","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/modules/encryption.md","filePath":"zh-Hans/deep-dive/modules/encryption.md","lastUpdated":1795341187000}`),d=e({name:`zh-Hans/deep-dive/modules/encryption.md`,setup(e){return(e,u)=>(o(),t(`div`,null,[u[0]||=i(`h1`,{id:`客户端加密-v2-1`,tabindex:`-1`},[r(`客户端加密 v2.1 `),i(`a`,{class:`header-anchor`,href:`#客户端加密-v2-1`,"aria-label":`Permalink to “客户端加密 v2.1”`},`​`)],-1),u[1]||=i(`p`,null,[r(`插件把加密后的文件上传到远端，下载后解密回本地。本文规定 `),i(`code`,null,`Encryption`),r(` 模块中加密算法的实现。`)],-1),u[2]||=i(`p`,null,`本模块的加密实现欢迎自愿审计。`,-1),a(l,{canvas:s(c)},null,8,[`canvas`]),u[3]||=n(`<h2 id="术语" tabindex="-1">术语 <a class="header-anchor" href="#术语" aria-label="Permalink to “术语”">​</a></h2><h3 id="记号" tabindex="-1">记号 <a class="header-anchor" href="#记号" aria-label="Permalink to “记号”">​</a></h3><ul><li>IV = 初始化向量 = Nonce</li><li>B = 字节（Byte）</li><li>b = 比特（bit）</li><li>1KiB = 1024B</li><li>|| = 拼接</li></ul><h3 id="威胁模型与约束" tabindex="-1">威胁模型与约束 <a class="header-anchor" href="#威胁模型与约束" aria-label="Permalink to “威胁模型与约束”">​</a></h3><p><strong>实现信任</strong>：</p><ul><li>客户端在模块之外共享密码。共享渠道不在范围之内，模块不需要实现自己的密钥交换。</li><li>操作系统或 Obsidian 运行时未被攻破。</li></ul><p><strong>实现不信任</strong>：</p><ul><li>后端服务器</li><li>传输层</li></ul><p><strong>实现防护</strong>：</p><ul><li>未授权访问</li><li>未授权修改或文件截断</li><li>加密与<a href="./../asymmetric-storage">非对称存储</a>结合可以产生更好的混淆，因为它压平了层级结构并随机化了文件基名。</li></ul><p><strong>实现无法做到</strong>：</p><ul><li>阻止文件回滚到之前的版本</li><li>阻止意外的重命名或移动</li><li>阻止服务器端的删除</li><li>混淆文件大小或修改时间</li><li>混淆文件总数</li><li>混淆远端根目录名</li><li>混淆服务器键值文件元数据存储中的密钥</li></ul><h3 id="算法" tabindex="-1">算法 <a class="header-anchor" href="#算法" aria-label="Permalink to “算法”">​</a></h3><ul><li><code>SHA256</code>：从用户信息生成确定且唯一的盐，用于获得<em>主密钥</em>。</li><li><code>Argon2id</code>：从盐和用户密码生成<em>主密钥</em>，在每次用户信息 / 密码变更时使用。</li><li><code>HKDF-SHA-256</code>：从<em>主密钥</em>派生<em>根文件密钥</em>、<em>名称密钥</em>和<em>元数据密钥</em>，并从<em>根文件密钥</em>和<em>文件盐</em>派生<em>文件密钥</em>，在每次同步时使用。</li><li><code>CSPRNG</code>：（<code>crypto.getRandomValues()</code>）生成随机的<em>文件盐</em>，在每次文件加密时使用</li><li><code>AES-GCM-256</code>：加密文件内容和元数据值的主要算法，在每次文件加密时使用</li><li><code>AES-GCM-SIV-256</code>：加密文件 / 文件夹名称的算法，在每次文件加密时使用</li><li><code>Base64URL</code>：把二进制数据转换为 ASCII 以便存入文件名</li><li><code>Base64</code>：把二进制数据转换为 ASCII 以便存入元数据值</li></ul><h3 id="密钥与数据结构" tabindex="-1">密钥与数据结构 <a class="header-anchor" href="#密钥与数据结构" aria-label="Permalink to “密钥与数据结构”">​</a></h3><ul><li><em>用户密码</em>：用户密码的原始字符串</li><li><em>认证标签</em>（auth tag）：16B，由 <code>AES-GCM-256</code> 生成，用于校验数据完整性</li><li><em>主盐</em>（master salt）：16B，用于给<em>用户密码</em>加盐得到<em>主密钥</em>，由用户信息的 <code>SHA256</code> 生成</li><li><em>主密钥</em>（master key）：32B，由 <code>Argon2id</code> 从<em>用户密码</em>和<em>主盐</em>生成的确定性强密钥</li><li><em>名称密钥</em>（name key）：32B，从<em>主密钥</em>派生，用于加密文件名</li><li><em>根文件密钥</em>（root file key）：32B，从<em>主密钥</em>派生，用于为每个文件生成<em>文件密钥</em></li><li><em>元数据密钥</em>（meta key）：32B，从<em>主密钥</em>派生，用于加密元数据值</li><li><em>文件密钥</em>（file key）：32B，从<em>根文件密钥</em>和随机的<em>文件盐</em>派生</li><li><em>文件盐</em>（file salt）：16B，纯随机，每次加密或解密文件时用于派生<em>文件密钥</em></li><li><em>文件密钥盐</em>（file key salt）：32B，<em>文件盐</em> || 8B 表示的加密文件大小 的 <code>SHA256</code></li><li><em>分块 nonce</em>（chunk nonce）：12B，以 12B 表示的分块索引。</li><li><em>加密文件 / 文件夹名</em>：<code>AES-GCM-SIV</code> 加密文件名后的 <code>Base64URL</code></li><li><em>加密文件 / 文件夹路径</em>：所有祖先层级的<em>加密文件 / 文件夹名</em>以 <code>/</code> 连接。</li><li><em>文件分块</em>：131,088B，文件按 128KiB 分块并经 <code>AES-GCM-256</code> 加密后的片段（末块可以更小）</li><li><em>加密文件内容</em>：<em>文件盐</em> || 所有分块按顺序拼接</li><li><em>元数据 nonce</em>（meta nonce）：12B，纯随机，每次元数据值加密经 <code>CSPRNG</code> 生成</li><li><em>加密元数据值</em>：<em>元数据 nonce</em> || <code>AES-GCM-256</code> 密文（含 16B 认证标签）的 <code>Base64</code></li></ul><h2 id="启用与禁用" tabindex="-1">启用与禁用 <a class="header-anchor" href="#启用与禁用" aria-label="Permalink to “启用与禁用”">​</a></h2><p>该功能通过 <strong>Encryption</strong> 设置开关。密码存储在 Obsidian 的钥匙串中。记录存储存在时，切换开关会打开确认提示，类似<a href="./../../usage/settings#非对称存储">非对称存储</a>；只有在你按照<a href="./../../usage/remote-migration">远程迁移指南</a>完成远端数据迁移之后才确认。</p><h2 id="同步流程" tabindex="-1">同步流程 <a class="header-anchor" href="#同步流程" aria-label="Permalink to “同步流程”">​</a></h2><p>每次同步时，生成一个 promise 来获取<em>根文件密钥</em>、<em>名称密钥</em>和<em>元数据密钥</em>，按需 resolve 并缓存：</p><ul><li>起始检查：发现用户密码是空字符串或 undefined 时直接抛出</li><li>生成<em>主盐</em>：<strong>对配置的后端账户中通常可安全披露的区分数据（例如账户名 + 服务器 URL + 目录前缀）</strong>取 <code>SHA256</code>，截断为 16B。</li><li>用 <code>Argon2id</code>（32MB 内存、3 次迭代、1 线程）在<em>用户密码</em>和<em>主盐</em>上生成<em>主密钥</em></li><li>用 <code>HKDF-SHA-256</code> 派生<em>根文件密钥</em>（info: <code>root-file-key-v1</code>，无盐）、<em>名称密钥</em>（info: <code>name-key-v1</code>，无盐）和<em>元数据密钥</em>（info: <code>meta-key-v1</code>，无盐）</li><li>以<em>根文件密钥</em>、<em>名称密钥</em>和<em>元数据密钥</em> resolve</li></ul><p>然后进入遍历与同步逻辑：</p><ul><li>加密和解密隔离在远端<a href="./../file-system-wrappers">文件系统包装器</a>中。包装器透明地转换每个文件系统操作的键和内容。</li><li>&quot;Encryption&quot; 启用时假设所有文件都已加密，未启用时假设所有文件都是明文。</li></ul><h2 id="文件-文件夹路径加密" tabindex="-1">文件 / 文件夹路径加密 <a class="header-anchor" href="#文件-文件夹路径加密" aria-label="Permalink to “文件 / 文件夹路径加密”">​</a></h2><ul><li>所有路径应以 UTF-8 表示并规范化为 Unicode NFC</li><li>级联加密整条路径链，对每个文件名（应是独立名称，如 <code>bar</code>、<code>foo.md</code>）： <ul><li>用 <code>AES-GCM-SIV-256</code> 加密文件名，密钥：<em>名称密钥</em>，内容：文件名，nonce：固定为 <code>file-name-v1</code> 的 UTF-8 字节。</li><li>对上述结果做 <code>Base64URL</code> 得到最终名称</li></ul></li><li>例如，加密 <code>foo/bar/a.md</code> 的完整路径时，先加密 <code>foo</code>，再加密 <code>bar</code> 文件夹，最后加密 <code>a.md</code>。</li><li>用全局内存缓存加速相同路径的文件路径加密 / 解密，上限 10K 条目。</li><li>不加密用户的远端根目录。</li></ul><h2 id="文件加密" tabindex="-1">文件加密 <a class="header-anchor" href="#文件加密" aria-label="Permalink to “文件加密”">​</a></h2><ul><li>输入原始文件和原始文件大小</li><li>经 <code>CSPRNG</code> 生成随机 16B 的<em>文件盐</em></li><li>计算加密文件大小：<code>原始大小 + 16B + ceil(原始大小 / 128KiB) * 16B</code></li><li>计算<em>文件密钥盐</em>：<em>文件盐</em> || 8B 表示的加密文件大小 的 <code>SHA256</code></li><li>用<em>根文件密钥</em>的 <code>HKDF-SHA-256</code> 计算<em>文件密钥</em>（盐：<em>文件密钥盐</em>，info: <code>file-key-v1</code>）。</li><li>把文件内容切成 128KiB 的分块，末块用特殊大小，对每个分块： <ul><li>取从 0 开始的分块索引，以 12B 表示作为<em>分块 nonce</em></li><li>用<em>文件密钥</em>和<em>分块 nonce</em> 经 <code>AES-GCM-256</code> 加密这 128KiB</li><li>每块 = 密文（128KiB = 131,072B）+ 认证标签（16B）= 131,088B</li></ul></li><li>把文件拼接为：<em>文件盐</em> || 所有分块按顺序</li></ul><h2 id="元数据加密" tabindex="-1">元数据加密 <a class="header-anchor" href="#元数据加密" aria-label="Permalink to “元数据加密”">​</a></h2><ul><li>用 <code>HKDF-SHA-256</code> 从<em>主密钥</em>派生<em>元数据密钥</em>（info: <code>meta-key-v1</code>，无盐）</li><li>对每个非空的元数据值： <ul><li>经 <code>CSPRNG</code> 生成随机 12B 的<em>元数据 nonce</em></li><li>用<em>元数据密钥</em>和<em>元数据 nonce</em> 经 <code>AES-GCM-256</code> 加密 UTF-8 编码的值</li><li>编码为<em>元数据 nonce</em> || 密文（含 16B 认证标签）的 <code>Base64</code></li></ul></li><li>解密反转这个过程：<code>Base64</code> 解码、切分<em>元数据 nonce</em>（前 12B）与密文、用 <code>AES-GCM-256</code> 解密</li></ul><h2 id="一次性解密" tabindex="-1">一次性解密 <a class="header-anchor" href="#一次性解密" aria-label="Permalink to “一次性解密”">​</a></h2><ul><li>输入加密文件和以字节计的加密大小</li><li>切出前 16B 作为<em>文件盐</em></li><li>计算<em>文件密钥盐</em>：<em>文件盐</em> || 8B 表示的加密文件大小 的 <code>SHA256</code></li><li>用<em>根文件密钥</em>的 <code>HKDF-SHA-256</code> 计算<em>文件密钥</em>（盐：<em>文件密钥盐</em>，info: <code>file-key-v1</code>）。</li><li>继续切成 131,088B 的片段（末块例外），对每个片段： <ul><li>以<em>分块索引</em>作为<em>分块 nonce</em></li><li>用<em>分块 nonce</em> + <em>文件密钥</em>经 <code>AES-GCM-256</code> 解密该块，认证标签不匹配时抛出 <code>Decryption error: incorrect encryption password or the data is corrupted</code> 并跳过该文件</li></ul></li><li>拼接解密后的内容</li></ul><h2 id="流式解密" tabindex="-1">流式解密 <a class="header-anchor" href="#流式解密" aria-label="Permalink to “流式解密”">​</a></h2><p>流式解密接收一个 <code>ReadableStream</code>，生成另一个 <code>ReadableStream</code>，在流之间管道式解密。</p><ul><li>输入以字节计的加密大小，并接受文件内容的顺序二进制流</li><li>内部拆分并拼接分块</li><li>例如，收到的第一个二进制大小为 2,000,000B 时，range 解密器： <ul><li>剥离前 16B 作为<em>文件盐</em></li><li>为每个分块累加计数器，剥下接下来的 1966380B 作为 15 个<em>已完成分块</em></li><li>把最后 33604B 保存为一个<em>未完成分块</em>，存入缓冲区</li><li>像一次性解密那样解密这 15 个<em>已完成分块</em></li><li>拼接内容，并管道输出到新流。</li><li>下一个二进制流分块到达时，它把缓冲区中的内容与新二进制的开头一定数量的字节拼接，作为第一个<em>已完成分块</em>。</li><li>重复直到原始流结束，此时类把缓冲区中剩余内容视为一个<em>已完成分块</em>，直接解密，管道输出到新流，然后结束它。</li></ul></li></ul><h2 id="流式加密" tabindex="-1">流式加密 <a class="header-anchor" href="#流式加密" aria-label="Permalink to “流式加密”">​</a></h2><p>流式加密与流式解密走对称的路径。</p><ul><li>输入以字节计的未加密大小和文件内容的 <code>ReadableStream</code>。</li><li>计算加密大小：<code>原始大小 + 16B + ceil(原始大小 / 128KiB) * 16B</code></li><li>计算<em>文件密钥盐</em>：<em>文件盐</em> || 8B 表示的加密文件大小 的 <code>SHA256</code></li><li>用<em>根文件密钥</em>的 <code>HKDF-SHA-256</code> 计算<em>文件密钥</em>（盐：<em>文件密钥盐</em>，info: <code>file-key-v1</code> 常量字符串）。</li><li>在原始流之上创建一个 <code>TransformStream</code>。</li><li>持续读取流，加密并维护一个原始字节缓冲区：预留一个流分块后缓冲区不足 128KiB 时继续读取；大于 128KiB 时，加密缓冲区中最多数量的 128KiB 分块并发出。流结束时，加密并发出缓冲区中的剩余内容。</li><li>第一个发出的内容前面应带<em>文件盐</em>。</li></ul><h2 id="文件-文件夹名解密" tabindex="-1">文件 / 文件夹名解密 <a class="header-anchor" href="#文件-文件夹名解密" aria-label="Permalink to “文件 / 文件夹名解密”">​</a></h2><ul><li>输入文件名并做 <code>Base64URL</code> 解码得到原始字节</li><li>用 <code>AES-GCM-SIV-256</code> 配合<em>名称密钥</em>和 nonce 解密文件名的其余部分（尽量使用缓存）</li></ul><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to “实现”">​</a></h2><p>实现只应使用：</p><ul><li>Web Crypto</li><li><code>hash-wasm</code> 的 <code>argon2id</code> 导出</li><li><code>@noble/ciphers/aes.js</code> 的 <code>gcmsiv</code> 导出</li></ul><p>加密功能会作为一个 Sync Engine 可选模块干净地集成在 <code>encryption</code> 包内，它提供一个 <a href="./../file-system-wrappers"><code>RemoteFsWrapper</code></a>：</p><p>第二个参数接收内存数据库实例和<em>用户密码</em>。</p><p><code>getUid()</code>、<code>checkConnection()</code>、<code>options</code>：保持原样。</p><p><code>read()</code>：转发给原始 FS 之前加密键，原始 FS 返回后解密。</p><p><code>readStream()</code>：转发给原始 FS 之前加密键，创建一个新的 <code>transformStream</code> 中继原始流。</p><p><code>write()</code>：转发给原始 FS 之前加密键、内容和元数据值。</p><p><code>writeStream()</code>：转发给原始 FS 之前加密键、元数据值和流内容。</p><p><code>delete()</code>、<code>mkdir()</code>：转发给原始 FS 之前加密键。</p><p><code>stat()</code>：转发前加密键，原始 FS 返回后解密 <code>Stat</code> 中的 <code>key</code> 和元数据值。</p><p><code>list()</code>：转发前加密键，原始 FS 返回后解密 <code>Array&lt;Stat&gt;</code> 中的 <code>key</code> 和元数据值。</p><p>路径段和派生密钥会被缓存，跨同步运行持久化。缓存基于从 context 获取的 Uni-KV <code>memoryDB</code>，类似 <a href="./../file-system-wrappers">Context 包装器</a>，只在信号变化时重置：</p><ul><li>存储元数据：<code>EncryptionDBMeta</code></li><li>存储模式：<code>EncryptionDBSchema</code></li><li>作用域：<code>decryptedToEncrypted</code> 和 <code>encryptedToDecrypted</code> 存储</li></ul><p>行为：</p><ul><li><code>encryptionMarker</code> = <code>RemoteFs.getUid()</code> || <code>~</code> || <em>用户密码</em></li><li>缓存的派生密钥保存在 store meta 的 <code>encryptionKeys</code> 字段中</li><li>仅在包装器激活时执行一次：检查 store meta 的 <code>encryptionMarker</code> 是否与当前一致。不一致时清空存储和 <code>encryptionKeys</code>，并把元数据更新为当前 uid。</li></ul>`,56)]))}});export{u as __pageData,d as default};